require __DIR__.'/app/bootstrap.php';$token=(string)($_GET['token']??$_POST['token']??'');$valid=false;$row=null;if(preg_match('/^[a-f0-9]{64}$/',$token)){$q=$pdo->prepare('SELECT * FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW()');$q->execute([hash('sha256',$token)]);$row=$q->fetch();$valid=(bool)$row;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pw=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm']??'');if(!$valid)$error='لینک نامعتبر یا منقضی شده است.';elseif(strlen($pw)<12)$error='رمز عبور باید حداقل ۱۲ نویسه باشد.';elseif($pw!==$confirm)$error='تکرار رمز عبور مطابقت ندارد.';else{$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$row['user_id']]);$pdo->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([$row['id']]);flash('success','رمز عبور با موفقیت تغییر کرد.');header('Location: '.site_url('login.php'));exit;}}
render_header('تعیین رمز جدید');?><main class="container"><div class="form-card narrow"><h1>تعیین رمز جدید</h1><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><?php if($valid):?><form method="post"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><div class="form-group"><label>رمز جدید (حداقل ۱۲ نویسه)</label><input type="password" name="password" minlength="12" required autocomplete="new-password"></div><div class="form-group"><label>تکرار رمز جدید</label><input type="password" name="confirm" minlength="12" required autocomplete="new-password"></div><button class="btn">ذخیره رمز جدید</button></form><?php else:?><p>این لینک بازیابی معتبر نیست یا مهلتش تمام شده است.</p><?php endif;?></div></main><?php render_footer();
